import { Component, DOCUMENT, HostListener, effect, inject } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { Prefs } from './prefs';

@Component({ selector: 'app-root', imports: [RouterOutlet], template: '<router-outlet />' })
export class App {
  readonly prefs = inject(Prefs);
  private readonly doc = inject(DOCUMENT);

  constructor() {
    // Keep the address in step with the preferences, so a reload or a copied link keeps them.
    effect(() => {
      const query = this.prefs.query();
      const view = this.doc.defaultView;
      if (view) view.history.replaceState(view.history.state, '', view.location.pathname + query + view.location.hash);
    });
  }

  /** The portal header renders its skip link as a bare "#id". With <base href="/"> that address
   *  leaves the current page and drops the query, so fragment links are resolved in the document here. */
  @HostListener('document:click', ['$event']) fragment(event: MouseEvent): void {
    const link = (event.target as Element | null)?.closest?.('a[href^="#"]');
    const id = link?.getAttribute('href')?.slice(1);
    const target = id ? this.doc.getElementById(id) : null;
    if (!target) return;
    event.preventDefault();
    target.focus();
    target.scrollIntoView();
  }
}

