import { Component, computed, inject, input, signal } from '@angular/core';
import { HwButtonDirective } from '@hawiyah/angular';
import { Prefs } from './prefs';

const ARABIC_RUN = /([\u0600-\u06FF]+(?:[ \u00A0]+[\u0600-\u06FF]+)*)/;

/** Code listing. The packages have no code-block component, so this is a plain
 *  figure with pre/code and token-only styling (recorded as a package gap). */
@Component({
  selector: 'app-code',
  imports: [HwButtonDirective],
  styleUrl: './code.css',
  template: `<figure class="code">
    <figcaption class="bar">
      @if (file()) { <span class="file" dir="ltr">{{ file() }}</span> } @else { <span class="caption hw-type" data-scale="body-sm">{{ caption() }}</span> }
      <button hwButton variant="ghost" size="sm" type="button" (click)="copy()">{{ copied() ? prefs.t('Copied', 'تم النسخ') : prefs.t('Copy', 'نسخ') }}</button>
    </figcaption>
    <div class="swap">
      @for (item of items(); track item.key) {
        <pre dir="ltr" [class.wrap]="wrap()" [attr.tabindex]="wrap() ? null : 0" [animate.enter]="animate() ? 'swap-in' : 'swap-none'" animate.leave="swap-out"><code>@for (part of item.parts; track $index) {<span [class.arabic]="part.arabic" [attr.lang]="part.arabic ? 'ar' : null">{{ part.text }}</span>}</code></pre>
      }
    </div>
    <span class="hw-sr-only" role="status">{{ copied() ? prefs.t('Copied to the clipboard', 'تم النسخ إلى الحافظة') : '' }}</span>
  </figure>`,
})
export class Code {
  readonly prefs = inject(Prefs);
  /** A file name, shown in the monospace face. Use caption for a plain label instead. */
  readonly file = input('');
  readonly caption = input('');
  readonly text = input.required<string>();
  /** Changing the key replaces the listing and cross-fades; changing only the text does not. */
  readonly swapKey = input.required<string>();
  readonly wrap = input(false);
  readonly animate = input(false);
  /** Arabic runs are set in the sans face: the monospace face has no Arabic glyphs. */
  readonly items = computed(() => [{ key: this.swapKey(), parts: this.text().split(ARABIC_RUN).filter(Boolean).map((text) => ({ text, arabic: /[\u0600-\u06FF]/.test(text) })) }]);
  readonly copied = signal(false);
  private timer?: ReturnType<typeof setTimeout>;

  copy(): void {
    const done = () => { this.copied.set(true); clearTimeout(this.timer); this.timer = setTimeout(() => this.copied.set(false), 2000); };
    navigator.clipboard?.writeText(this.text()).then(done, () => {});
  }
}

