import { Component, afterNextRender, computed, inject, signal } from '@angular/core';
import { HwBadgeComponent, HwButtonDirective, HwCardComponent, HwTextFieldComponent, HwToggleGroupComponent } from '@hawiyah/angular';
import { Choice, type Framework, type Manager } from './choice';
import { Code } from './code';
import { Prefs } from './prefs';
import { firstComponent, installCommand, styleImport } from './snippets';

@Component({
  selector: 'app-install',
  imports: [HwBadgeComponent, HwButtonDirective, HwCardComponent, HwTextFieldComponent, HwToggleGroupComponent, Code],
  styleUrl: './install.css',
  template: `<section class="install" aria-labelledby="install-title">
