    <ol class="steps" role="list">
      <li class="step">
        <div class="head"><span aria-hidden="true"><hw-badge variant="outline">1</hw-badge></span>
          <h3 class="hw-type" data-scale="heading-sm">{{ prefs.t('Install the styles and one adapter', 'ثبّت حزمة الأنماط ومهايئًا واحدًا') }}</h3></div>
        <app-code [caption]="prefs.t('Terminal', 'الطرفية')" [text]="command()" [swapKey]="choice.fw() + choice.pm()" [wrap]="true" [animate]="ready()" />
      </li>
      <li class="step">
        <div class="head"><span aria-hidden="true"><hw-badge variant="outline">2</hw-badge></span>
          <h3 class="hw-type" data-scale="heading-sm">{{ prefs.t('Import the styles once', 'استورد الأنماط مرة واحدة') }}</h3></div>
        <app-code [file]="styles().file" [text]="styles().text" [swapKey]="choice.fw()" [wrap]="true" [animate]="ready()" />
        <p class="note hw-type" data-scale="body-sm">{{ prefs.t('The theme applies to any element that carries', 'تُطبَّق السمة على أي عنصر يحمل الخاصية') }} <code dir="ltr">data-hw-theme="dga"</code>{{ prefs.t('.', '.') }}</p>
      </li>
      <li class="step">
        <div class="head"><span aria-hidden="true"><hw-badge variant="outline">3</hw-badge></span>
          <h3 class="hw-type" data-scale="heading-sm">{{ prefs.t('Render a first component', 'اعرض أول مكوّن') }}</h3></div>
        <div class="pair">
          <app-code class="listing" [file]="first().file" [text]="first().text" [swapKey]="choice.fw()" [animate]="ready()" />
          <hw-card class="result" variant="outlined">
            <span hwCardHeader class="hw-type" data-scale="heading-sm">{{ prefs.t('Result', 'النتيجة') }}</span>
            <div class="swap">
              @for (key of [choice.fw()]; track key) {
                <div class="live" [animate.enter]="ready() ? 'swap-in' : 'swap-none'" animate.leave="swap-out">
                  <hw-text-field [controlId]="'first-name-' + key" name="name" [label]="name()" [required]="true" />
                  <div><button hwButton type="button">{{ action() }}</button></div>
                </div>
              }
            </div>
            <p hwCardFooter class="note hw-type" data-scale="body-xs">{{ prefs.t('Rendered on this page by', 'معروضة في هذه الصفحة بواسطة') }} <span dir="ltr">&#64;hawiyah/angular 0.2.1</span>{{ prefs.t('. The four adapters share the same styles.', '. تشترك المهايئات الأربعة في الأنماط نفسها.') }}</p>
          </hw-card>
        </div>
      </li>
    </ol>
  </section>`,
})
export class Install {
  readonly prefs = inject(Prefs);
  readonly choice = inject(Choice);
  /** False during the first render so that only later changes cross-fade. */
  readonly ready = signal(false);

  readonly frameworks = [
    { value: 'js', label: 'JavaScript' }, { value: 'react', label: 'React' },
    { value: 'vue', label: 'Vue' }, { value: 'angular', label: 'Angular' },
  ];
  readonly managers = [{ value: 'npm', label: 'npm' }, { value: 'pnpm', label: 'pnpm' }, { value: 'yarn', label: 'yarn' }];

  readonly name = computed(() => this.prefs.t('Full name', 'الاسم الكامل'));
  readonly action = computed(() => this.prefs.t('Continue', 'متابعة'));
  readonly command = computed(() => installCommand(this.choice.fw(), this.choice.pm()));
  readonly styles = computed(() => styleImport(this.choice.fw()));
  readonly first = computed(() => firstComponent(this.choice.fw(), this.name(), this.action()));

  constructor() { afterNextRender(() => this.ready.set(true)); }

  setFramework(value: string | string[]): void { this.choice.fw.set(value as Framework); }
  setManager(value: string | string[]): void { this.choice.pm.set(value as Manager); }
}

