import { DOCUMENT, Injectable, inject, signal } from '@angular/core';

export type Lang = 'ar' | 'en';
export type Dir = 'rtl' | 'ltr';
export type Mode = 'light' | 'dark';

/** Reader preferences. Language, direction and colour mode are independent of each other.
 *  Prototype convention: ?lang=ar|en&dir=rtl|ltr&mode=light|dark (dir defaults from lang only when absent). */
@Injectable({ providedIn: 'root' })
export class Prefs {
  private readonly doc = inject(DOCUMENT);
  readonly lang = signal<Lang>('ar');
  readonly dir = signal<Dir>('rtl');
  readonly mode = signal<Mode>('light');

  constructor() {
    const q = new URLSearchParams(this.doc.defaultView?.location.search ?? '');
    const lang = q.get('lang') === 'en' ? 'en' : 'ar';
    const dir = (q.get('dir') as Dir | null) ?? (lang === 'ar' ? 'rtl' : 'ltr');
    this.set(lang, dir === 'ltr' ? 'ltr' : 'rtl', q.get('mode') === 'dark' ? 'dark' : 'light');
  }
  set(lang: Lang, dir: Dir, mode: Mode): void {
    this.lang.set(lang); this.dir.set(dir); this.mode.set(mode);
    const root = this.doc.documentElement;
    root.lang = lang; root.dir = dir;
    root.setAttribute('data-hw-theme', 'dga');
    root.setAttribute('data-hw-mode', mode);
    root.setAttribute('data-hw-density', 'comfortable');
  }
  /** The preferences as a query string, for links and the address bar. */
  query(): string { return `?lang=${this.lang()}&dir=${this.dir()}&mode=${this.mode()}`; }
  /** An address inside the guide that carries the current preferences. */
  href(path: string): string { return path + this.query(); }
  /** Pick the string for the current language. */
  t(en: string, ar: string): string { return this.lang() === 'ar' ? ar : en; }
}

