import { ADAPTER, type Framework, type Manager } from './choice';

export interface Snippet { file: string; text: string; }

const ADD: Record<Manager, string> = { npm: 'npm install', pnpm: 'pnpm add', yarn: 'yarn add' };

export function installCommand(fw: Framework, pm: Manager): string {
  return `${ADD[pm]} @hawiyah/styles ${ADAPTER[fw]}`;
}

export function styleImport(fw: Framework): Snippet {
  if (fw === 'angular') return { file: 'src/styles.css', text: `@import '@hawiyah/styles/styles.css';` };
  const file = fw === 'react' ? 'src/main.tsx' : fw === 'vue' ? 'src/main.ts' : 'main.js';
  return { file, text: `import '@hawiyah/styles/styles.css';` };
}

/** The first component: one text field and one button. Labels follow the page language. */
export function firstComponent(fw: Framework, name: string, action: string): Snippet {
  switch (fw) {
    case 'react':
      return { file: 'Example.tsx', text:
`import { Button, TextField } from '@hawiyah/react';

export function Example() {
  return (
    <>
      <TextField label="${name}" name="name" required />
      <Button>${action}</Button>
    </>
  );
}` };
    case 'vue':
      return { file: 'Example.vue', text:
`<script setup lang="ts">
import { Button, TextField } from '@hawiyah/vue';
</script>

<template>
  <TextField label="${name}" name="name" required />
  <Button>${action}</Button>
</template>` };
    case 'angular':
